function makeRunePistol() {
  const g = makePistol();
  const FUR = new Set([woodMat, woodDark, gunPoly, gunOlive, gunTan]);
  const tex = camoTile(RUNE_FINISH_KEY);
  const mat = new THREE.MeshStandardMaterial({ color: 0xe6e2d6, map: tex, roughness: 0.6, metalness: 0.03, emissive: 0xffffff, emissiveMap: runeFinish.glowTex || null, emissiveIntensity: 0.3 });
  // CB-325: since J149 the pistol's coat is its own finish per part (partFinish, a weaponFinishRole on each coated
  // material, as the paint registry reads it), not the shared furniture; those parts take the rune finish too.
  g.traverse((o) => { if (o.isMesh && (FUR.has(o.material) || (g.userData.partFinish && o.material?.userData?.weaponFinishRole))) o.material = mat; });
  g.name = 'rune-pistol';
  return g;
}
